function restoreGroupIdentity(){document.body.classList.remove('atta-apartment-page');delete document.body.dataset.property;headerElement.querySelector('.logo').href='/';headerElement.querySelector('nav').innerHTML=groupNavTemplate;footerElement.innerHTML=groupFooterTemplate;if(window.renderGroupFooter)window.renderGroupFooter();document.documentElement.style.setProperty('--ink',site.brand.color);document.documentElement.style.setProperty('--gold',site.brand.accent);document.documentElement.style.setProperty('--surface','#F5F2EE');document.documentElement.style.setProperty('--line','#E6D6C8');document.querySelectorAll('.logo img').forEach(el=>{el.src=site.brand.logo||'/assets/hlh-logo.png';el.alt=(site.brand.title||'HLH')+' · Hotel & Luxury Housing'});}async function route(){const path=location.pathname;const propertyDestinations={'/palais-wia':window.HLH_SITE_LINKS?.wia?.site,'/atta':window.HLH_SITE_LINKS?.atta?.site,'/atta/reserver':window.HLH_SITE_LINKS?.atta?.reservation,'/hotel-astral':window.HLH_SITE_LINKS?.astral?.site};if(propertyDestinations[path]){location.replace(propertyDestinations[path]);return}const property=site.hotels.find(h=>'/'+h.slug===path);if(property){renderHotel(property.id);if(property.id==='atta'){bindAttaHeroSlider();bindAttaBooking()}return}const attaRoute={'/atta/reserver':'reservation','/atta/appartements-premium':'appartements-premium','/atta/coworking':'coworking','/atta/salle-de-sport':'salle-de-sport','/atta/contact':'contact'}[path];if(attaRoute==='reservation')return renderAttaReservation();if(attaRoute)return renderAttaPage(attaRoute);restoreGroupIdentity();if(path==='/'&&window.renderGroupHome&&window.renderGroupHome(path))return;if(window.renderGroupPage&&window.renderGroupPage(path))return;if(path==='/'){applyHome();return}document.querySelector('#search')?.remove();if(path.startsWith('/chambre/'))return renderRoom(path.split('/')[2]);if(path==='/recherche')return renderSearch();if(path==='/reservation')return renderCheckout();if(path==='/suivi')return renderTracking();if(path==='/mon-compte')return renderAccount();if(path==='/gestion')return renderAdmin();if(path==='/guide')return renderGuide();if(path==='/hebergements')return page(tx('Nos adresses & hébergements','Our properties & accommodation'),hotelCards()+`<div class="featurestrip"><h2>${tx('Chambres & appartements','Rooms & apartments')}</h2>${roomCards(site.rooms.filter(r=>r.active))}</div>`);if(path==='/galerie')return renderGallery();if(path==='/offres')return page(tx('Les offres HLH','HLH offers'),`<div class="offergrid">${offerCards()}</div>`);if(path==='/faq')return page(tx('Questions fréquentes','Frequently asked questions'),faqHTML(site.faqs));if(path==='/confidentialite')return page(tx('Confidentialité','Privacy'),`<p>${esc(tr(site.brand.privacy))}</p>`);if(path==='/contact')return renderContact();if(path==='/actualites')return page(tx('Actualités HLH','HLH news'),articlesHTML());if(path.startsWith('/article/')){const a=site.articles.find(a=>a.id===path.split('/')[2]&&a.active);return a?page(tr(a.title),`${a.image?img(a.image,a.title,'roomhero'):''}<p>${esc(a.date)}</p><div class="articlebody">${esc(tr(a.body)).replace(/\n/g,'<br>')}</div>`):notFound()};if(path==='/a-propos')return page(tx('Une hospitalité pensée ici.','Hospitality rooted here.'),`<p class="lead">${esc(tr(site.brand.intro))}</p>${hotelCards()}`);if(path==='/experiences')return page(tx('Plus qu’un séjour.','More than a stay.'),`<div class="offergrid"><article><h3>La Quintessence & L’Alchimie</h3><p>${tx('Les rendez-vous gastronomiques du Palais WIA.','Dining experiences at Palais WIA.')}</p><a href="/palais-wia" class="textbutton">Palais WIA</a></article><article><h3>Coworking</h3><p>${tx('Travailler au cœur du Plateau.','Work in the heart of Plateau.')}</p><a href="/coworking" class="textbutton">ATTA</a></article><article><h3>${tx('Réunions & business','Meetings & business')}</h3><p>${tx('Vos déplacements et rendez-vous à Abidjan.','Your business trips and meetings in Abidjan.')}</p><a href="/entreprises" class="textbutton">HLH Business</a></article></div>`);if(['/long-sejour','/entreprises','/coworking'].includes(path)){const type=path==='/long-sejour'?'long':path==='/entreprises'?'business':'coworking',h=type==='business'?'all':'atta';return page(type==='long'?tx('Le Plateau comme adresse.','Make Plateau your address.'):type==='business'?tx('Vos équipes à Abidjan.','Your teams in Abidjan.'):tx('Travaillez au cœur du Plateau.','Work in the heart of Plateau.'),`<div class="hotelintro">${img(hById(type==='business'?'astral':'atta').image,'HLH')}<div><h2>${type==='long'?tx('Meublé ou non meublé. À votre rythme.','Furnished or unfurnished. At your own pace.'):type==='business'?tx('Une solution selon votre mission.','A solution tailored to your mission.'):tx('Un espace pour vos journées professionnelles.','A space for your working day.')}</h2><p>${type==='long'?tx('Pour quelques semaines ou plusieurs mois, préparez votre installation à ATTA avec notre équipe.','For a few weeks or several months, plan your move to ATTA with our team.'):type==='business'?tx('Hébergement, long séjour et réunions : indiquez les besoins de vos collaborateurs ou de votre délégation.','Accommodation, long stays and meetings: tell us what your team or delegation needs.'):tx('Découvrez le coworking des Résidences ATTA et demandez une visite.','Explore coworking at Résidences ATTA and request a visit.')}</p><button class="dark" data-inquiry="${type==='business'?'Offre entreprise':type==='long'?'Long séjour ATTA':'Visite coworking ATTA'}" data-kind="${type}" data-hotelid="${h}">${tx('Demander une proposition','Request an offer')}</button></div></div>${type==='long'?roomCards(site.rooms.filter(r=>r.hotel==='atta'&&r.active)):''}`)}return notFound()}
document.addEventListener('click',e=>{const link=e.target.closest('a[href]');if(!link||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||link.target||link.hasAttribute('download'))return;const url=new URL(link.href,location.href),attaPaths=new Set(['/atta','/atta/reserver','/atta/appartements-premium','/atta/coworking','/atta/salle-de-sport','/atta/contact']);if(url.origin!==location.origin||!attaPaths.has(url.pathname)||!location.pathname.startsWith('/atta'))return;e.preventDefault();history.pushState({},'',url.pathname+url.search+url.hash);route()},true);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.detail){modal.close();location.href='/'+hById(b.dataset.detail).slug}if(b.dataset.inquiry)inquiry(b.dataset.inquiry,b.dataset.kind||(/entreprise/i.test(b.dataset.inquiry)?'business':/long/i.test(b.dataset.inquiry)?'long':/coworking/i.test(b.dataset.inquiry)?'coworking':'contact'),b.dataset.hotelid||'all');if(b.dataset.add){const selectedRoom=site.rooms.find(r=>r.id===b.dataset.add);if(selectedRoom?.hotel==='atta'){location.href='/atta/reserver?category='+encodeURIComponent(b.dataset.category||'');return}addRoom(b.dataset.add,b.dataset.category||'')}if(b.hasAttribute('data-checkout'))await renderCheckout();if(b.hasAttribute('data-book')){modal.close();if(document.body.classList.contains('group-portal-page')&&window.openGroupBookingChooser){window.openGroupBookingChooser('');return}if(location.pathname==='/'){document.querySelector('#search').scrollIntoView({behavior:'smooth'});document.querySelector('[name=hotel]').focus()}else location.href=document.body.dataset.property==='atta'?'/atta/reserver':'/recherche'+(document.body.dataset.property?'?hotel='+encodeURIComponent(document.body.dataset.property):'')}if(b.dataset.lightbox){const urls=site.hotels.flatMap(h=>h.gallery);const at=urls.indexOf(b.dataset.lightbox);showLightbox(urls,at,b.dataset.caption)}if(b.dataset.filter)document.querySelectorAll('[data-hotel]').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.hotel!=='all'&&x.dataset.hotel!==b.dataset.filter);if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);await renderCheckout()}});
document.addEventListener('change',async e=>{if(e.target.dataset.quantity!==undefined){cart[Number(e.target.dataset.quantity)].quantity=Math.min(20,Math.max(1,Number(e.target.value)||1));await renderCheckout()}if(e.target.dataset.extra){if(e.target.checked)selectedExtras.push(e.target.dataset.extra);else selectedExtras=selectedExtras.filter(x=>x!==e.target.dataset.extra);await renderCheckout()}});
function showLightbox(urls,index,caption){open(`<h3>${esc(caption)}</h3>${img(urls[index],caption,'lightboxphoto')}<div class="actions"><button class="outline" id="prevphoto">${tx('Précédente','Previous')}</button><span>${index+1} / ${urls.length}</span><button class="outline" id="nextphoto">${tx('Suivante','Next')}</button></div>`);document.querySelector('#prevphoto').onclick=()=>showLightbox(urls,(index-1+urls.length)%urls.length,caption);document.querySelector('#nextphoto').onclick=()=>showLightbox(urls,(index+1)%urls.length,caption)}
document.querySelector('.close').onclick=()=>modal.close();document.querySelector('.menu').onclick=()=>{const nav=document.querySelector('#header nav');const open=nav.classList.toggle('open');document.querySelector('.menu').setAttribute('aria-expanded',String(open));document.querySelector('.menu').setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu')};document.querySelector('#language').onclick=()=>{lang=lang==='fr'?'en':'fr';localStorage.setItem('hlh-language',lang);const url=new URL(location.href);url.searchParams.set('lang',lang);location.href=url.toString()};window.addEventListener('popstate',()=>route());window.addEventListener('scroll',()=>document.querySelector('header').classList.toggle('scrolled',window.scrollY>70));
async function boot(){try{const results=await Promise.all([api('content'),api('identity')]);site=results[0].content;contentRevision=results[0].revision;currentUser=results[1].user;isAdmin=results[1].admin;site.brand.color=String(site.brand.color||'').toLowerCase()==='#0c3439'?'#0B0B0B':(site.brand.color||'#0B0B0B');site.brand.accent=String(site.brand.accent||'').toLowerCase()==='#c5a573'?'#BDA38B':(site.brand.accent||'#BDA38B');site.brand.logo=site.brand.logo||'/assets/hlh-logo.png';const verifiedContacts={wia:{phone:'+225 05 44 04 38 38 / +225 27 22 59 04 74',email:'info@palaiswia.com'},atta:{phone:'+225 05 66 07 37 36',email:'info.atta@hotel-hlh.com'},astral:{phone:'+225 27 23 40 02 39 / +225 05 86 86 94 50',email:'info.astral@hotel-hlh.com'}};for(const hotel of site.hotels){hotel.logo=hotel.logo||(hotel.id==='wia'?'/assets/palais-wia-logo.png':hotel.id==='astral'?'/assets/astral-logo.png':hotel.id==='atta'?'/assets/atta-logo.svg':'');if(hotel.id==='atta'&&hotel.logo==='/assets/atta-logo.png')hotel.logo='/assets/atta-logo.svg';const contact=verifiedContacts[hotel.id]||{};if(!hotel.phone)hotel.phone=contact.phone||'';if(hotel.id==='atta')hotel.email=contact.email||hotel.email||'';else if(!hotel.email)hotel.email=contact.email||'';}const brochureContent={wia:{old:'Au quartier des Ambassades, le Palais WIA accueille vos séjours dans une atmosphère intime. Découvrez ses neuf chambres et suites, le restaurant La Quintessence, le bar L’Alchimie, sa piscine et son jardin.',details:'Au quartier des Ambassades, le Palais WIA accueille vos séjours dans une atmosphère intime. Découvrez ses neuf chambres premium et suites, le restaurant gastronomique, le bar et sa terrasse, un espace événementiel extérieur, le jardin, la piscine design et le fitness center.'},atta:{old:'Le Plateau comme adresse. Pour quelques nuits, une mission de plusieurs semaines ou une installation durable, ATTA vous offre l’indépendance d’un appartement au cœur du quartier des affaires. La résidence propose un espace coworking, une piscine et une salle de sport.',details:'Les Résidences ATTA proposent 57 appartements premium (studios, 2 pièces et 3 pièces), meublés ou non meublés, au cœur du Plateau. La résidence dispose d’une cuisine équipée, du Wi-Fi, d’une piscine, d’une salle de sport, d’un espace de coworking, d’une vue sur la lagune, d’une navette hôtel-aéroport, d’un parking sécurisé sur demande et d’un site sécurisé 24h/24.'},astral:{old:'Situé dans la zone industrielle de Yopougon, l’Hôtel Astral accompagne vos déplacements professionnels avec 25 chambres classiques de 30 m², 4 appartements de 60 m², un restaurant, une salle de réunion et une salle de sport.',details:'Situé rue R16, dans la zone industrielle de Yopougon, l’Hôtel Astral accompagne vos déplacements professionnels avec 25 chambres standard, 4 appartements, un restaurant proposant un menu du jour et un buffet, une salle de réunion connectée, une salle de sport équipée, le Wi-Fi, un parking sécurisé et une navette hôtel-aéroport.'}};for(const hotel of site.hotels){const copy=brochureContent[hotel.id];if(copy&&hotel.details===copy.old)hotel.details=copy.details;}const brochureAmenities={wia:{old:['La Quintessence','L’Alchimie','Piscine','Jardin','Fitness','Salle de réunion'],next:['Restaurant gastronomique','Bar et terrasse','Espace événementiel extérieur','Jardin','Piscine design','Fitness center','Wi-Fi','Chaînes câblées','Sécurité 24h/24']},atta:{old:['Meublés et non meublés','Court et long séjour','Coworking','Piscine','Salle de sport','Vue sur la lagune'],next:['57 appartements premium','Studios, 2 pièces et 3 pièces','Meublés et non meublés','Coworking','Piscine','Salle de sport','Vue sur la lagune','Navette aéroport','Parking sécurisé sur demande','Sécurité 24h/24']},astral:{old:['Restaurant','Salle de réunion','Salle de sport','Parking'],next:['Restaurant','Menu du jour','Buffet','Salle de réunion connectée','Salle de sport équipée','Wi-Fi','Parking sécurisé','Navette hôtel-aéroport']}};for(const hotel of site.hotels){const list=brochureAmenities[hotel.id];if(list&&JSON.stringify(hotel.amenities)===JSON.stringify(list.old))hotel.amenities=list.next;}const brochurePhotos={wia:'/assets/wia-room.jpg',atta:'/assets/atta-room.jpg',astral:'/assets/astral-room.jpg'},oldPhotos=['/assets/hero.png','/assets/photo1.jpg','/assets/photo2.jpg'];for(const hotel of site.hotels){if(!hotel.image||oldPhotos.includes(hotel.image))hotel.image=brochurePhotos[hotel.id]||hotel.image;if(!hotel.gallery?.length||hotel.gallery.some(url=>oldPhotos.includes(url)))hotel.gallery=[hotel.image];}for(const room of site.rooms){if(room.id==='astral-classique'&&room.name==='Chambre Classique')room.name='Chambre standard';if(!room.image||oldPhotos.includes(room.image))room.image=brochurePhotos[room.hotel]||room.image;}try{const draft=JSON.parse(sessionStorage.getItem("hlh-draft")||"null");if(draft){cart=draft.cart.filter(x=>site.rooms.some(r=>r.id===x.room&&r.active));selectedExtras=draft.selectedExtras||[];coupon=draft.coupon||"";bookingState={...bookingState,...draft.bookingState};}}catch{}document.documentElement.style.setProperty('--ink',site.brand.color);document.documentElement.style.setProperty('--gold',site.brand.accent);document.querySelectorAll('.logo img').forEach(el=>{el.src=site.brand.logo||'/assets/hlh-logo.png';el.alt=(site.brand.title||'HLH')+' · Hotel & Luxury Housing'});document.documentElement.lang=lang;document.querySelector('#language').textContent=lang==='en'?'FR':'EN';await route();translateStatic(document.querySelector('header'));translateStatic(document.querySelector('footer'));if(site.brand.whatsapp){const link=document.createElement('a');link.className='whatsapp';link.href='https://wa.me/'+site.brand.whatsapp.replace(/\D/g,'');link.textContent='WhatsApp';link.target='_blank';link.rel='noopener';document.body.append(link)}}catch(e){page(tx('Le site est momentanément indisponible.','The site is temporarily unavailable.'),`<p>${esc(e.message)}</p><button class="dark" onclick="location.reload()">${tx('Réessayer','Retry')}</button>`)}finally{document.documentElement.removeAttribute('data-route-loading');delete document.documentElement.dataset.routeProperty}};window.addEventListener('DOMContentLoaded',boot);
